958: function lawsAnswer(question) {
959:   const q = String(question).trim();
960:   const ql = q.toLowerCase();
961:   if (/^(привет|здрав|добрый|хай|ку\b)/.test(ql)) {
962:     return {
963:       text: 'Здравия желаю! Я — нейро-помощник по законодательству RMRP (база: forum.rmrp.ru/forums/laws).\n\nСпросите, например:\n• «какое наказание за убийство?»\n• «как проводится задержание / арест?»\n• «что грозит за хранение оружия?»\n• «статья за кражу»',
964:       sources: []
965:     };
966:   }
967:   const qTokens = tokenize(q);
968:   if (!qTokens.length) {
969:     return { text: 'Сформулируйте вопрос по законодательству RMRP — например: «какое наказание за угон?» или «порядок проведения обыска».', sources: [] };
970:   }
971:   const scored = [];
972:   for (const code of LAWS.codes || []) {
973:     for (const a of code.articles || []) {
974:       const tTitle = tokenize((a.num || '') + ' ' + (a.title || ''));
975:       const tText = tokenize(a.text || '');
976:       let score = 0;
977:       for (const t of qTokens) {
978:         const st = stem(t);
979:         if (tTitle.some(w => w === t)) score += 8;
980:         else if (tTitle.some(w => stem(w) === st)) score += 5;
981:         if (tText.includes(t)) score += 2;
982:         else if (t.length >= 5 && tText.some(w => stem(w) === st)) score += 1;
983:       }
984:       if (score > 0) scored.push({ score, code, a });
985:     }
986:   }
987:   scored.sort((x, y) => y.score - x.score || (x.a.num || '').localeCompare(y.a.num || ''));
988:   const top = scored.slice(0, 3).filter(x => x.score >= 5);
989:   if (!top.length) {
990:     return {
991:       text: 'Точной статьи по такому запросу в базе не нашёл. Уточните формулировку («наказание за…», «порядок задержания», «лицензия на оружие», «статья …») либо откройте нужный акт напрямую:',
992:       sources: (LAWS.codes || []).map(c => ({ title: c.title, url: c.url }))
993:         .concat((LAWS.laws || []).slice(0, 8).map(l => ({ title: l.title, url: l.url })))
994:     };
995:   }
996:   const parts = top.map((x, i) => {
997:     const body = String(x.a.text || '').slice(0, 900);
998:     return `${i + 1}. «${x.code.short || x.code.title}» — Статья ${x.a.num}. ${x.a.title}\n${body}${String(x.a.text || '').length > 900 ? '…' : ''}`;
999:   });
1000:   const seen = new Set();
1001:   const sources = [];
1002:   for (const x of top) {
1003:     if (!seen.has(x.code.url)) { seen.add(x.code.url); sources.push({ title: x.code.title, url: x.code.url }); }
1004:   }
1005:   return {
1006:     text: 'По вашему вопросу нашлось в базе законодательства RMRP:\n\n' + parts.join('\n\n') + '\n\n⚖ Полный текст — по ссылке на источник. База носит справочный характер: в спорных ситуациях сверяйтесь с первоисточником.',
1007:     sources
1008:   };
1009: }
