688: SECTIONS.reports = async function (root) {
689:   const { reports } = await api('/api/reports');
690:   const tabs = isCmd() ? [
691:     ['pending', 'На рассмотрении'], ['approved', 'Одобренные'], ['rejected', 'Отклонённые'], ['all', 'Все']
692:   ] : [['all', 'Мои рапорта']];
693:   const list = reportsFilter === 'all' ? reports : reports.filter(r => r.status === reportsFilter);
694: 
695:   root.innerHTML = `
696:     <div class="section-head">
697:       <div class="section-title">📋 Рапорта на повышение<span class="t-sub">Подача, рассмотрение и история рапортов</span></div>
698:       <button class="btn btn-gold" id="btn-new-report">＋ Подать рапорт</button>
699:     </div>
700:     <div class="panel glass">
701:       <div class="tabs" id="report-tabs">
702:         ${tabs.map(([k, label]) => `<button class="tab ${reportsFilter === k ? 'active' : ''}" data-f="${k}">${label}${k !== 'all' && isCmd() ? ` (${reports.filter(r => r.status === k).length})` : ''}</button>`).join('')}
703:       </div>
704:       <div class="doc-list" style="margin-top:14px" id="report-list">
705:         ${list.length ? list.map(r => reportItemHtml(r)).join('') : emptyHtml('📋', 'Рапортов в этой категории нет')}
706:       </div>
707:     </div>`;
708: 
709:   $('#btn-new-report').addEventListener('click', () => openReportModal());
710:   $$('#report-tabs .tab').forEach(t => t.addEventListener('click', () => { reportsFilter = t.dataset.f; SECTIONS.reports(root); }));
711:   $$('#report-list [data-open]').forEach(el => el.addEventListener('click', () => openReportView(el.dataset.open, reports)));
712: };
