719:       <div class="di-sub">${isCmd() ? esc(r.author.fio) + (r.author.callsign ? ` (${esc(r.author.callsign)})` : '') + ' · ' : ''}${fmtDateTime(r.createdAt)} · ${r.totalPoints} баллов</div>
720:     </div>
721:     <div class="di-right">${statusBadge(r.status)}</div>
722:   </div>`;
