725: function openReportView(id, reports) {
726:   const r = (reports || []).find(x => x.id === id);
727:   if (!r) return;
728:   const canReview = isCmd() && r.status === 'pending';
729:   const canDelete = (r.userId === me.id && r.status === 'pending') || isCmd();
730:   openModal({
731:     title: `Рапорт №${r.num} — ${statusText(r.status)}`,
732:     wide: true,
733:     body: reportDocHtml(r) + (canReview ? `
734:       <hr class="hr">
735:       <div class="form-section-title">Решение командования</div>
736:       <label class="field"><span>Комментарий (необязательно)</span>
737:         <textarea id="rv-comment" rows="2" maxlength="1000" placeholder="Например: баллы подтверждены, звание присвоить"></textarea></label>` : ''),
738:     footer: `
739:       ${canDelete ? `<button class="btn btn-danger" id="rv-delete" style="margin-right:auto">🗑 Удалить</button>` : ''}
740:       <button class="btn btn-ghost" id="rv-close">Закрыть</button>
741:       ${canReview ? `
742:         <button class="btn btn-danger" id="rv-reject">❌ Отклонить</button>
743:         <button class="btn btn-success" id="rv-approve">✅ Одобрить и присвоить звание</button>` : ''}`
744:   });
745:   $('#rv-close').addEventListener('click', closeModal);
746:   if (canReview) {
747:     const review = async decision => {
748:       if (decision === 'approved' &&
749:         !await confirmDialog(`Одобрить рапорт №${r.num}?\nСотруднику будет присвоено звание «${r.requestedRank}», а баланс баллов установлен в ${r.remainder}.`, 'Одобрить', false)) return;
750:       try {
751:         await api(`/api/reports/${r.id}/review`, { method: 'PATCH', body: { decision, comment: $('#rv-comment').value } });
752:         closeModal();
753:         toast(decision === 'approved' ? `Рапорт №${r.num} одобрен` : `Рапорт №${r.num} отклонён`, decision === 'approved' ? 'success' : 'warn');
754:         SECTIONS.reports($('#content'));
755:         refreshBadges().catch(() => {});
756:       } catch (e) { modalError(e.message); }
757:     };
758:     $('#rv-approve').addEventListener('click', () => review('approved'));
759:     $('#rv-reject').addEventListener('click', () => review('rejected'));
760:   }
761:   if (canDelete) {
762:     $('#rv-delete').addEventListener('click', async () => {
763:       if (!await confirmDialog(`Удалить рапорт №${r.num} безвозвратно?`)) return;
764:       try {
765:         await api('/api/reports/' + r.id, { method: 'DELETE' });
766:         closeModal(); toast('Рапорт удалён', 'success');
767:         SECTIONS.reports($('#content'));
768:       } catch (e) { toast(e.message, 'error'); }
769:     });
770:   }
771: }
