773: function openReportModal() {
774:   const next = meta.promotions.find(p => p.from === me.rank);
775:   const rankOptions = meta.promotions
776:     .map(p => p.to)
777:     .filter((v, i, arr) => arr.indexOf(v) === i)
778:     .map(to => {
779:       const pr = meta.promotions.find(p => p.to === to);
780:       return `<option value="${esc(to)}" ${next && next.to === to ? 'selected' : ''}>${esc(to)}${pr && pr.note ? ` (${pr.note})` : ''}</option>`;
781:     }).join('');
782:   const manual = { total: false, rem: false };
783: 
784:   openModal({
785:     title: 'Подача рапорта на повышение',
786:     wide: true,
787:     body: `
788:       <div id="rp-form">
789:         <div class="form-section-title">Звание</div>
790:         <div class="grid-2">
791:           <label class="field"><span>Текущее звание</span><input type="text" value="${esc(me.rank)}" disabled></label>
792:           <label class="field"><span>Прошу присвоить звание</span><select id="rp-rank">${rankOptions}</select></label>
793:         </div>
794: 
795:         <div class="form-section-title">Проделанная работа (количество + баллы)</div>
796:         <div class="grid-2">
797:           <label class="field"><span>Поставки, шт. (30 б. за каждую)</span><input type="number" id="rp-dc" min="0" value="0"></label>
798:           <label class="field"><span>Поставки — суммарно баллов</span><input type="number" id="rp-dp" min="0" value="0"></label>
799:           <label class="field"><span>Штрафы, шт. (10 б.)</span><input type="number" id="rp-fc" min="0" value="0"></label>
800:           <label class="field"><span>Штрафы — суммарно баллов</span><input type="number" id="rp-fp" min="0" value="0"></label>
801:           <label class="field"><span>Аресты, шт. (45 б.)</span><input type="number" id="rp-ac" min="0" value="0"></label>
802:           <label class="field"><span>Аресты — суммарно баллов</span><input type="number" id="rp-ap" min="0" value="0"></label>
803:           <label class="field"><span>Отбития КрАЗа, шт. (30 б.)</span><input type="number" id="rp-kc" min="0" value="0"></label>
804:           <label class="field"><span>КрАЗ — суммарно баллов</span><input type="number" id="rp-kp" min="0" value="0"></label>
805:         </div>
806:         <label class="field"><span>Прочее (ГМП, МП, заложники и т.д.) — описание</span>
807:           <textarea id="rp-other" rows="2" maxlength="2000" placeholder="Например: ГМП 12.10 — 100 б.; освобождение заложника 14.10 — 100 б."></textarea></label>
808:         <label class="field"><span>Прочее — суммарно баллов</span><input type="number" id="rp-otherp" min="0" value="0"></label>
809: 
810:         <div class="form-section-title">Баллы</div>
811:         <div class="grid-2">
812:           <label class="field"><span>Баллы с прошлого повышения (остаток)</span><input type="number" id="rp-prev" min="0" value="${me.points}"></label>
813:           <label class="field"><span>Ссылка на сообщение с остатком</span><input type="url" id="rp-link" maxlength="500" placeholder="https://discord.com/channels/..."></label>
814:           <label class="field"><span>Баллы подсчитаны для следующего повышения</span><input type="number" id="rp-total" min="0" value="0"></label>
815:           <label class="field"><span>Остаток баллов после повышения</span><input type="number" id="rp-rem" min="0" value="0"></label>
816:         </div>
817:         <label class="field"><span>Дата рапорта</span><input type="date" id="rp-date" value="${todayStr()}"></label>
818:         <label class="field"><span>Дополнительно (доказательства, примечания)</span>
819:           <textarea id="rp-evidence" rows="3" maxlength="3000" placeholder="Ссылки на скриншоты, пояснения..."></textarea></label>
820:       </div>
821:       <div id="rp-preview" class="hidden"></div>`,
822:     footer: `
823:       <button class="btn btn-ghost" id="rp-toggle">👁 Предпросмотр рапорта</button>
824:       <button class="btn btn-ghost" id="rp-cancel">Отмена</button>
825:       <button class="btn btn-gold" id="rp-submit">⚡ Подать рапорт</button>`
826:   });
827: 
828:   const gv = id => Math.max(0, Math.round(+($(id) || {}).value || 0));
829:   const autoPoints = [
830:     ['#rp-dc', '#rp-dp', 30], ['#rp-fc', '#rp-fp', 10],
831:     ['#rp-ac', '#rp-ap', 45], ['#rp-kc', '#rp-kp', 30]
832:   ];
833:   function cost() {
834:     const p = meta.promotions.find(x => x.to === $('#rp-rank').value);
835:     return p ? p.points : 0;
836:   }
837:   function recalc() {
838:     autoPoints.forEach(([c, p, rate]) => { $(p).value = gv(c) * rate; });
839:     if (!manual.total) {
840:       $('#rp-total').value = gv('#rp-prev') + gv('#rp-dp') + gv('#rp-fp') + gv('#rp-ap') + gv('#rp-kp') + gv('#rp-otherp');
841:     }
842:     if (!manual.rem) {
843:       $('#rp-rem').value = Math.max(0, gv('#rp-total') - cost());
844:     }
845:   }
846:   autoPoints.forEach(([c]) => $(c).addEventListener('input', recalc));
847:   ['#rp-prev', '#rp-otherp'].forEach(id => $(id).addEventListener('input', recalc));
848:   $('#rp-rank').addEventListener('change', () => { manual.rem = false; recalc(); });
849:   $('#rp-total').addEventListener('input', () => { manual.total = true; if (!manual.rem) $('#rp-rem').value = Math.max(0, gv('#rp-total') - cost()); });
850:   $('#rp-rem').addEventListener('input', () => { manual.rem = true; });
851:   recalc();
852: 
853:   function collect() {
854:     return {
855:       num: 'XXX', author: me, currentRank: me.rank,
856:       requestedRank: $('#rp-rank').value,
857:       deliveries: { count: gv('#rp-dc'), points: gv('#rp-dp') },
858:       fines: { count: gv('#rp-fc'), points: gv('#rp-fp') },
859:       arrests: { count: gv('#rp-ac'), points: gv('#rp-ap') },
860:       kraz: { count: gv('#rp-kc'), points: gv('#rp-kp') },
861:       other: $('#rp-other').value, otherPoints: gv('#rp-otherp'),
862:       prevPoints: gv('#rp-prev'), prevPointsLink: $('#rp-link').value.trim(),
863:       totalPoints: gv('#rp-total'), remainder: gv('#rp-rem'),
864:       date: $('#rp-date').value, evidence: $('#rp-evidence').value
865:     };
866:   }
867:   $('#rp-toggle').addEventListener('click', () => {
868:     const show = $('#rp-preview').classList.contains('hidden');
869:     if (show) $('#rp-preview').innerHTML = reportDocHtml(collect(), true);
870:     $('#rp-preview').classList.toggle('hidden', !show);
871:     $('#rp-form').classList.toggle('hidden', show);
872:     $('#rp-toggle').textContent = show ? '✏ Вернуться к форме' : '👁 Предпросмотр рапорта';
873:   });
874:   $('#rp-cancel').addEventListener('click', closeModal);
875:   $('#rp-submit').addEventListener('click', async () => {
876:     const b = collect();
877:     if (!b.deliveries.count && !b.fines.count && !b.arrests.count && !b.otherPoints && !b.prevPoints) {
878:       return modalError('Рапорт пуст: укажите проделанную работу или баллы с прошлого повышения.');
879:     }
880:     try {
881:       await api('/api/reports', {
882:         method: 'POST',
883:         body: {
884:           requestedRank: b.requestedRank,
885:           deliveriesCount: b.deliveries.count, deliveriesPoints: b.deliveries.points,
886:           finesCount: b.fines.count, finesPoints: b.fines.points,
887:           arrestsCount: b.arrests.count, arrestsPoints: b.arrests.points,
888:           krazCount: b.kraz.count, krazPoints: b.kraz.points,
889:           other: b.other, otherPoints: b.otherPoints,
890:           prevPoints: b.prevPoints, prevPointsLink: b.prevPointsLink,
891:           totalPoints: b.totalPoints, remainder: b.remainder,
892:           date: b.date, evidence: b.evidence
893:         }
894:       });
895:       closeModal();
896:       toast('Рапорт подан. Ожидайте решения командования.', 'success');
897:       SECTIONS.reports($('#content'));
898:       refreshBadges().catch(() => {});
899:     } catch (e) { modalError(e.message); }
900:   });
901: }
