app.post('/api/chat', auth, (req, res) => {
  const b = req.body || {};
  const text = clip(b.text, 2000).trim();
  const att = sanitizeAtt(b.att);
  if (!text && !att) return res.status(400).json({ error: 'Пустое сообщение' });
  const msg = { id: uid(), userId: req.user.id, text, ts: now() };
  if (att) msg.att = att;
  pushChat(msg);
  broadcast({ type: 'chat', message: decorateMsg(msg) });
  res.json({ message: decorateMsg(msg) });
});

/* Редактирование своего сообщения чата */
app.patch('/api/chat/:id', auth, (req, res) => {
  const m = db.chat.find(x => x.id === req.params.id);
  if (!m) return res.status(404).json({ error: 'Сообщение не найдено' });
  if (m.userId !== req.user.id) return res.status(403).json({ error: 'Можно редактировать только свои сообщения' });
  const text = clip((req.body || {}).text, 2000).trim();
  if (!text) return res.status(400).json({ error: 'Пустое сообщение' });
  m.text = text;
  m.editedAt = now();
  saveDb();
  broadcast({ type: 'chat-edit', message: decorateMsg(m) });
  res.json({ message: decorateMsg(m) });
});

/* Удаление своего сообщения чата (командование может удалить любое) */
app.delete('/api/chat/:id', auth, (req, res) => {
  const m = db.chat.find(x => x.id === req.params.id);
  if (!m) return res.status(404).json({ error: 'Сообщение не найдено' });
  if (m.userId !== req.user.id && !isCommand(req.user)) return res.status(403).json({ error: 'Можно удалять только свои сообщения' });
  db.chat = db.chat.filter(x => x.id !== m.id);
  saveDb();
  broadcast({ type: 'chat-delete', id: m.id });
  res.json({ ok: true });
});

