function appendChatMsg(box, m, prev) {
  if (chatState.rendered.has(m.id)) return;
  chatState.rendered.add(m.id);
  if (!prev || dayKey(prev.ts) !== dayKey(m.ts)) {
    const sep = document.createElement('div');
    sep.className = 'day-sep';
    sep.textContent = fmtDate(m.ts);
    box.appendChild(sep);
  }
  const grouped = prev && prev.userId === m.userId && (m.ts - prev.ts) < 5 * 60000 && dayKey(prev.ts) === dayKey(m.ts);
  const mine = m.userId === me.id;
  const a = m.author || {};
  const el = document.createElement('div');
  el.className = `msg ${mine ? 'mine' : ''} ${grouped ? 'grouped' : ''}`;
  el.dataset.mid = m.id;
  el.innerHTML = `
    <div class="msg-avatar">${avatarHtml(a, 'sm', false)}</div>
    <div class="msg-body">
      ${grouped ? '' : `<div class="msg-author"><span class="name-${esc(a.role || 'staff')}">${esc(a.callsign ? a.callsign + ' · ' : '')}${esc(a.fio || '')}</span><span class="ma-rank">${esc(a.rank || '')}</span></div>`}
      <div class="bubble">${m.text ? nl2br(m.text) : ''}${msgAttHtml(m.att)}</div>
      <div class="msg-time">${fmtTime(m.ts)}${m.editedAt ? ' <span class="msg-edited">(изменено)</span>' : ''}
        ${mine ? `<span class="msg-actions">
          <button class="msg-act" data-act="edit" title="Редактировать сообщение">✏</button>
          <button class="msg-act" data-act="del" title="Удалить сообщение">🗑</button>
        </span>` : ''}
      </div>
    </div>`;
  if (mine) {
    el.querySelector('[data-act="edit"]').addEventListener('click', () => openChatEditModal(m.id));
    el.querySelector('[data-act="del"]').addEventListener('click', () => deleteChatMsg(m.id));
  }
  box.appendChild(el);
}

/* ---------- Редактирование / удаление своих сообщений чата ---------- */
function openChatEditModal(id) {
  const m = chatState.messages.find(x => x.id === id);
  if (!m) return;
  openModal({
    title: 'Редактирование сообщения',
    body: `<label class="field"><span>Текст сообщения</span>
      <textarea id="ce-text" rows="4" maxlength="2000">${esc(m.text)}</textarea></label>
      <p class="form-hint">Вложение (если было) останется без изменений. Отметка «изменено» будет видна всем.</p>`,
    footer: `<button class="btn btn-ghost" id="ce-cancel">Отмена</button>
             <button class="btn btn-primary" id="ce-save">💾 Сохранить</button>`
  });
  $('#ce-cancel').addEventListener('click', closeModal);
  $('#ce-save').addEventListener('click', async () => {
    const text = $('#ce-text').value.trim();
    if (!text) return modalError('Пустое сообщение');
    try {
      await api('/api/chat/' + id, { method: 'PATCH', body: { text } });
      closeModal();
      toast('Сообщение изменено', 'success');
    } catch (e) { modalError(e.message); }
  });
}

async function deleteChatMsg(id) {
  if (!await confirmDialog('Удалить это сообщение безвозвратно?')) return;
  try {
    await api('/api/chat/' + id, { method: 'DELETE' });
    toast('Сообщение удалено', 'success');
  } catch (e) { toast(e.message, 'error'); }
}

function onChatEdit(m) {
  const i = chatState.messages.findIndex(x => x.id === m.id);
  if (i > -1) chatState.messages[i] = Object.assign(chatState.messages[i], m);
  const el = $(`#chat-messages .msg[data-mid="${m.id}"]`);
  if (el) {
    const bubble = el.querySelector('.bubble');
    if (bubble) bubble.innerHTML = m.text ? nl2br(m.text) : '';
    const t = el.querySelector('.msg-time');
    if (t && !t.querySelector('.msg-edited')) t.insertAdjacentHTML('afterbegin', '');
    const time = el.querySelector('.msg-time');
    if (time) time.innerHTML = `${fmtTime(m.ts)} <span class="msg-edited">(изменено)</span>` +
      (m.userId === me.id ? `<span class="msg-actions">
        <button class="msg-act" data-act="edit" title="Редактировать сообщение">✏</button>
        <button class="msg-act" data-act="del" title="Удалить сообщение">🗑</button>
      </span>` : '');
    if (m.userId === me.id) {
      time.querySelector('[data-act="edit"]').addEventListener('click', () => openChatEditModal(m.id));
      time.querySelector('[data-act="del"]').addEventListener('click', () => deleteChatMsg(m.id));
    }
  }
}

function onChatDelete(id) {
  chatState.messages = chatState.messages.filter(x => x.id !== id);
  chatState.rendered.delete(id);
  const el = $(`#chat-messages .msg[data-mid="${id}"]`);
  if (el) el.remove();
}

