/* ---------- Заявки на позывной: рассмотрение старшим составом ---------- */
async function loadCsRequests(box) {
  if (!box) return;
  try {
    const d = await api('/api/callsigns');
    const pending = d.requests.filter(r => r.status === 'pending');
    const reviewed = d.requests.filter(r => r.status !== 'pending').slice(0, 10);
    if (!isCmd()) {
      box.innerHTML = d.requests.length ? `
        <div class="panel glass" style="margin-bottom:14px">
          <div class="panel-title">📡 Мои заявки на позывной</div>
          ${d.requests.slice(0, 5).map(r => `
            <div class="cs-req">
              <div class="cs-req-head"><b style="color:var(--gold)">${esc(r.callsign)}</b> ${statusBadge(r.status)}</div>
              <div class="muted" style="font-size:12.5px">подана ${fmtDateTime(r.createdAt)}${r.review && r.review.comment ? ' · комментарий: ' + esc(r.review.comment) : ''}</div>
            </div>`).join('')}
        </div>` : '';
      return;
    }
    box.innerHTML = `
      <div class="panel glass" style="margin-bottom:14px">
        <div class="panel-title">📡 Заявки на позывные ${pending.length ? `<span class="badge" style="margin-left:6px">${pending.length}</span>` : ''}</div>
        <div class="panel-sub">Одобрение автоматически вносит позывной в реестр отдела и в профиль сотрудника</div>
        ${pending.length ? pending.map(r => `
          <div class="cs-req">
            <div class="cs-req-head"><b style="color:var(--gold)">${esc(r.callsign)}</b> ${statusBadge(r.status)}</div>
            <div class="cs-req-meta">${esc(r.user.fio)} · ${esc(r.user.rank)} · ${fmtDateTime(r.createdAt)}</div>
            ${r.comment ? `<div class="muted" style="font-size:13px">Комментарий: ${esc(r.comment)}</div>` : ''}
            <div class="cs-req-actions">
              <input type="text" class="cs-review-comment" placeholder="Комментарий (необязательно)" maxlength="500">
              <button class="btn btn-success btn-sm" data-cs-ok="${r.id}">✅ Одобрить и внести в реестр</button>
              <button class="btn btn-danger btn-sm" data-cs-no="${r.id}">❌ Отклонить</button>
            </div>
          </div>`).join('') : '<p class="muted">Новых заявок нет.</p>'}
        ${reviewed.length ? `<div class="cs-group-title" style="margin-top:10px">Рассмотренные ранее</div>` + reviewed.map(r => `
          <div class="cs-req">
            <div class="cs-req-head"><b style="color:var(--gold)">${esc(r.callsign)}</b> ${statusBadge(r.status)}</div>
            <div class="cs-req-meta">${esc(r.user.fio)} · рассмотрена ${r.review ? fmtDateTime(r.review.ts) : ''}${r.review && r.review.comment ? ' · ' + esc(r.review.comment) : ''}</div>
          </div>`).join('') : ''}
      </div>`;
    $$('[data-cs-ok]', box).forEach(b => b.addEventListener('click', () => reviewCs(b.dataset.csOk, 'approved', b)));
    $$('[data-cs-no]', box).forEach(b => b.addEventListener('click', () => reviewCs(b.dataset.csNo, 'rejected', b)));
  } catch (e) { box.innerHTML = ''; }
}

async function reviewCs(id, decision, btn) {
  const comment = (btn.closest('.cs-req-actions').querySelector('.cs-review-comment').value || '').trim();
  try {
    await api(`/api/callsigns/${id}/review`, { method: 'PATCH', body: { decision, comment } });
    toast(decision === 'approved' ? 'Позывной внесён в реестр' : 'Заявка отклонена', decision === 'approved' ? 'success' : 'warn');
    renderMemoBody();
  } catch (e) { toast(e.message, 'error'); }
}

/* ================= Вкладка: Вопрос / ответ ================= */
SECTIONS.qa = async function (root) {
  const { questions } = await api('/api/qa');
  root.innerHTML = `
    <div class="section-head">
      <div class="section-title">❓ Вопрос / ответ<span class="t-sub">Задайте вопрос — сотрудники отдела помогут ответом</span></div>
      <button class="btn btn-gold" id="btn-new-qa">＋ Задать вопрос</button>
    </div>
    <div class="qa-list">
      ${questions.length ? questions.map(q => `
        <div class="qa-card glass" data-qa="${q.id}">
          <div class="qa-head">
            <span class="qa-title">${esc(q.title)}</span>
            ${q.solved ? '<span class="status-badge approved">✅ Решено</span>' : '<span class="status-badge pending">Открыт</span>'}
          </div>
          <div class="qa-text">${esc(q.text.length > 180 ? q.text.slice(0, 180) + '…' : q.text)}</div>
          <div class="qa-meta">
            <span>👤 ${esc(q.author.fio)}${q.author.callsign ? ` (${esc(q.author.callsign)})` : ''}</span>
            <span>🕒 ${fmtDateTime(q.createdAt)}</span>
            <span>💬 ${q.answers.length} ${plural(q.answers.length, ['ответ', 'ответа', 'ответов'])}</span>
          </div>
        </div>`).join('') : emptyHtml('❓', 'Вопросов пока нет — задайте первый!')}
    </div>`;
  $('#btn-new-qa').addEventListener('click', () => qaModal());
  $$('.qa-card', root).forEach(el => el.addEventListener('click', () => openQaView(el.dataset.qa)));
};

function qaModal() {
  openModal({
    title: 'Новый вопрос',
    body: `
      <label class="field"><span>Заголовок вопроса *</span>
        <input type="text" id="qa-title" maxlength="140" placeholder="Например: как правильно отбить жетон при проверке?"></label>
      <label class="field"><span>Подробности *</span>
        <textarea id="qa-text" rows="5" maxlength="4000" placeholder="Опишите ситуацию подробнее — так проще помочь ответом..."></textarea></label>`,
    footer: `<button class="btn btn-ghost" id="qa-cancel">Отмена</button>
             <button class="btn btn-primary" id="qa-save">❓ Опубликовать</button>`
  });
  $('#qa-cancel').addEventListener('click', closeModal);
  $('#qa-save').addEventListener('click', async () => {
    try {
      await api('/api/qa', { method: 'POST', body: { title: $('#qa-title').value, text: $('#qa-text').value } });
      closeModal(); toast('Вопрос опубликован', 'success');
      SECTIONS.qa($('#content'));
    } catch (e) { modalError(e.message); }
  });
}

async function openQaView(id) {
  const { questions } = await api('/api/qa');
  const q = questions.find(x => x.id === id);
  if (!q) return;
  const canManage = q.userId === me.id || isCmd();
  openModal({
    title: q.title,
    wide: true,
    body: `
      <div class="qa-meta" style="margin-bottom:10px">
        <span>👤 ${esc(q.author.fio)}${q.author.callsign ? ` (${esc(q.author.callsign)})` : ''} · ${esc(q.author.rank || '')}</span>
        <span>🕒 ${fmtDateTime(q.createdAt)}</span>
        ${q.solved ? '<span class="status-badge approved">✅ Решено</span>' : '<span class="status-badge pending">Открыт</span>'}
      </div>
      <div class="doc-evidence" style="border-left-color:var(--accent)">${nl2br(q.text)}</div>
      <div class="form-section-title" style="margin-top:16px">💬 Ответы (${q.answers.length})</div>
      <div id="qa-answers">
        ${q.answers.length ? q.answers.map(a => `
          <div class="qa-answer glass">
            <div class="qa-meta">
              <span><b>${esc(a.author.fio)}${a.author.callsign ? ` (${esc(a.author.callsign)})` : ''}</b> · ${esc(a.author.rank || '')}</span>
              <span>🕒 ${fmtDateTime(a.createdAt)}</span>
              ${(a.userId === me.id || isCmd()) ? `<button class="btn btn-ghost btn-sm" data-del-ans="${a.id}" style="margin-left:auto">🗑</button>` : ''}
            </div>
            <div style="font-size:14px;margin-top:6px">${nl2br(a.text)}</div>
          </div>`).join('') : '<p class="muted">Ответов пока нет. Помогите товарищу — ответьте первым!</p>'}
      </div>
      <label class="field" style="margin-top:12px"><span>Ваш ответ</span>
        <textarea id="qa-ans-text" rows="3" maxlength="4000" placeholder="Поделитесь знанием..."></textarea></label>`,
    footer: `
      ${canManage ? `<button class="btn btn-ghost" id="qa-solved" style="margin-right:auto">${q.solved ? '↩ Открыть снова' : '✅ Отметить решённым'}</button>` : ''}
      ${canManage ? `<button class="btn btn-danger" id="qa-del">🗑 Удалить вопрос</button>` : ''}
      <button class="btn btn-ghost" id="qa-close">Закрыть</button>
      <button class="btn btn-primary" id="qa-ans-send">💬 Ответить</button>`
  });
  $('#qa-close').addEventListener('click', closeModal);
  $('#qa-ans-send').addEventListener('click', async () => {
    const text = $('#qa-ans-text').value.trim();
    if (!text) return modalError('Пустой ответ');
    try {
      await api(`/api/qa/${q.id}/answers`, { method: 'POST', body: { text } });
      closeModal(); toast('Ответ опубликован', 'success');
      openQaView(q.id);
      SECTIONS.qa($('#content'));
    } catch (e) { modalError(e.message); }
  });
  const solvedBtn = $('#qa-solved');
  if (solvedBtn) solvedBtn.addEventListener('click', async () => {
    try {
      await api('/api/qa/' + q.id, { method: 'PATCH', body: { solved: !q.solved } });
      closeModal(); openQaView(q.id); SECTIONS.qa($('#content'));
    } catch (e) { toast(e.message, 'error'); }
  });
  const delBtn = $('#qa-del');
  if (delBtn) delBtn.addEventListener('click', async () => {
    if (!await confirmDialog('Удалить вопрос и все ответы безвозвратно?')) return;
    try {
      await api('/api/qa/' + q.id, { method: 'DELETE' });
      closeModal(); toast('Вопрос удалён', 'success'); SECTIONS.qa($('#content'));
    } catch (e) { toast(e.message, 'error'); }
  });
  $$('[data-del-ans]').forEach(b => b.addEventListener('click', async () => {
    if (!await confirmDialog('Удалить этот ответ?')) return;
    try {
      await api(`/api/qa/${q.id}/answers/${b.dataset.delAns}`, { method: 'DELETE' });
      closeModal(); openQaView(q.id); SECTIONS.qa($('#content'));
    } catch (e) { toast(e.message, 'error'); }
  }));
}

/* ================= Вкладка: Нейро-помощник по законодательству RMRP (отдельный чат) ================= */
let aiHistory = [];
try { aiHistory = JSON.parse(localStorage.getItem('grom_ai_history') || '[]'); } catch (e) { aiHistory = []; }
const aiSave = () => { try { localStorage.setItem('grom_ai_history', JSON.stringify(aiHistory.slice(-60))); } catch (e) {} };

function aiMsgHtml(m) {
  if (m.role === 'user') {
    return `<div class="ai-msg mine"><div class="ai-bubble user">${nl2br(m.text)}</div><div class="ai-who">Вы</div></div>`;
  }
  return `<div class="ai-msg"><div class="ai-ava">⚖️</div>
    <div class="ai-bubble bot">${nl2br(m.text)}
      ${(m.sources && m.sources.length) ? `<div class="ai-sources">Источники: ${m.sources.map(s => safeUrl(s.url) ? `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>` : esc(s.title)).join(' · ')}</div>` : ''}
    </div><div class="ai-who">Нейро-помощник</div></div>`;
}

SECTIONS.ai = async function (root) {
  let info = { source: 'https://forum.rmrp.ru/forums/laws/', updated: '', codes: [], laws: [] };
  try { info = await api('/api/ai/info'); } catch (e) {}
  const totalArticles = (info.codes || []).reduce((s, c) => s + (c.articles || 0), 0);
  root.innerHTML = `
    <div class="section-head">
      <div class="section-title">⚖️ Нейро-помощник по законодательству RMRP<span class="t-sub">Бесплатный ИИ-справочник по законке сервера · база: forum.rmrp.ru/forums/laws</span></div>
      <button class="btn btn-ghost btn-sm" id="ai-clear">🧹 Очистить чат</button>
    </div>
    <div class="ai-wrap glass">
      <div class="ai-info">
        <span class="chip">📚 ${(info.codes || []).length} ${plural((info.codes || []).length, ['кодекс', 'кодекса', 'кодексов'])} / ${totalArticles} ${plural(totalArticles, ['статья', 'статьи', 'статей'])}</span>
        <span class="chip">🕒 база от ${info.updated ? fmtDate(new Date(info.updated).getTime()) : '—'}</span>
        <a class="chip" href="${esc(info.source)}" target="_blank" rel="noopener">🔗 первоисточник</a>
      </div>
      <div class="ai-messages" id="ai-messages">
        ${aiHistory.length ? aiHistory.map(aiMsgHtml).join('') : `
          <div class="ai-hello">
            <div class="ai-hello-ico">⚖️</div>
            <b>Здравия желаю! Я — нейро-помощник по законодательству RMRP.</b>
            <p>Отвечаю бесплатно по базе законодательства сервера (forum.rmrp.ru/forums/laws). Спросите, например:</p>
            <div class="ai-sugs">
              <button class="btn btn-ghost btn-sm ai-sug">какое наказание за убийство?</button>
              <button class="btn btn-ghost btn-sm ai-sug">статья за кражу</button>
              <button class="btn btn-ghost btn-sm ai-sug">порядок проведения задержания</button>
              <button class="btn btn-ghost btn-sm ai-sug">что грозит за хранение оружия?</button>
            </div>
          </div>`}
      </div>
      <div class="chat-input" style="border-top:1px solid var(--border);background:transparent">
        <div style="flex:1;min-width:0">
          <textarea id="ai-text" rows="1" maxlength="500" placeholder="Вопрос по законодательству RMRP..."></textarea>
        </div>
        <button class="btn btn-primary" id="ai-send" title="Спросить">⚡</button>
      </div>
    </div>`;
  const box = $('#ai-messages');
  box.scrollTop = box.scrollHeight;
  const input = $('#ai-text');
  const send = async (text) => {
    const q = (text != null ? text : input.value).trim();
    if (!q) return;
    input.value = '';
    aiHistory.push({ role: 'user', text: q });
    aiSave();
    box.insertAdjacentHTML('beforeend', aiMsgHtml({ role: 'user', text: q }));
    box.insertAdjacentHTML('beforeend', '<div class="ai-msg"><div class="ai-ava">⚖️</div><div class="ai-bubble bot ai-thinking">думаю…</div></div>');
    box.scrollTop = box.scrollHeight;
    try {
      const d = await api('/api/ai', { method: 'POST', body: { question: q } });
      const last = box.querySelector('.ai-thinking');
      if (last) last.parentElement.remove();
      aiHistory.push({ role: 'ai', text: d.answer.text, sources: d.answer.sources });
      aiSave();
      box.insertAdjacentHTML('beforeend', aiMsgHtml({ role: 'ai', text: d.answer.text, sources: d.answer.sources }));
    } catch (e) {
      const last = box.querySelector('.ai-thinking');
      if (last) last.parentElement.remove();
      toast(e.message, 'error');
    }
    box.scrollTop = box.scrollHeight;
  };
  $('#ai-send').addEventListener('click', () => send());
  input.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); } });
  $$('.ai-sug', root).forEach(b => b.addEventListener('click', () => send(b.textContent)));
  $('#ai-clear').addEventListener('click', async () => {
    if (!await confirmDialog('Очистить историю чата с нейро-помощником?', 'Очистить')) return;
    aiHistory = []; aiSave(); SECTIONS.ai(root);
  });
};

