+            ${r.comment ? `<div class="muted" style="font-size:13px">Комментарий: ${esc(r.comment)}</div>` : ''}
+            <div class="cs-req-actions">
+              <input type="text" class="cs-review-comment" placeholder="Комментарий (необязательно)" maxlength="500">
+              <button class="btn btn-success btn-sm" data-cs-ok="${r.id}">✅ Одобрить и внести в реестр</button>
+              <button class="btn btn-danger btn-sm" data-cs-no="${r.id}">❌ Отклонить</button>
+            </div>
+          </div>`).join('') : '<p class="muted">Новых заявок нет.</p>'}
+        ${reviewed.length ? `<div class="cs-group-title" style="margin-top:10px">Рассмотренные ранее</div>` + reviewed.map(r => `
+          <div class="cs-req">
+            <div class="cs-req-head"><b style="color:var(--gold)">${esc(r.callsign)}</b> ${statusBadge(r.status)}</div>
+            <div class="cs-req-meta">${esc(r.user.fio)} · рассмотрена ${r.review ? fmtDateTime(r.review.ts) : ''}${r.review && r.review.comment ? ' · ' + esc(r.review.comment) : ''}</div>
+          </div>`).join('') : ''}
+      </div>`;
+    $$('[data-cs-ok]', box).forEach(b => b.addEventListener('click', () => reviewCs(b.dataset.csOk, 'approved', b)));
+    $$('[data-cs-no]', box).forEach(b => b.addEventListener('click', () => reviewCs(b.dataset.csNo, 'rejected', b)));
+  } catch (e) { box.innerHTML = ''; }
+}
