input.newString:
$('#pf-save').addEventListener('click', async () => {
  try {
    const body = { badge: $('#pf-badge').value.trim() };
    if (isCmd() && $('#pf-callsign')) body.callsign = $('#pf-callsign').value.trim();
    const d = await api('/api/auth/me', { method: 'PATCH', body });
    me = d.user;
    renderUserChip();
    toast('Данные сохранены', 'success');
  } catch (e) { toast(e.message, 'error'); }
});

/* --- заявка на позывной (для рядового состава) --- */
const csReqBtn = $('#pf-cs-request');
if (csReqBtn) {
  csReqBtn.addEventListener('click', openCsRequestModal);
  (async () => {
    try {
      const d = await api('/api/callsigns');
      const box = $('#pf-cs-requests');
      if (box && d.requests.length) {
        box.innerHTML = d.requests.slice(0, 3).map(r => `
          <div class="cs-req">
            <div class="cs-req-head"><b style="color:var(--gold)">${esc(r.callsign)}</b> ${statusBadge(r.status)}</div>
            <div class="muted" style="font-size:12.5px">подана ${fmtDateTime(r.createdAt)}${r.review && r.review.comment ? ' · ' + esc(r.review.comment) : ''}</div>
          </div>`).join('');
      }
    } catch (e) {}
  })();
}

