function openCsRequestModal() {
  openModal({
    title: 'Заявка на позывной',
    body: `
      <p class="muted" style="margin-top:0">Позывной формируется по схеме: <b>(слово) + (две последние цифры статика) + «-й»</b>, например: <span class="memo-example">Лис 53-й</span>.
      После одобрения командованием позывной автоматически попадёт в реестр отдела.</p>
      <label class="field"><span>Желаемый позывной *</span>
        <input type="text" id="csr-callsign" maxlength="60" placeholder="Лис 53-й"></label>
      <label class="field"><span>Комментарий командованию</span>
        <input type="text" id="csr-comment" maxlength="500" placeholder="Например: статик 1353"></label>`,
    footer: `<button class="btn btn-ghost" id="csr-cancel">Отмена</button>
             <button class="btn btn-gold" id="csr-send">📡 Подать заявку</button>`
  });
  $('#csr-cancel').addEventListener('click', closeModal);
  $('#csr-send').addEventListener('click', async () => {
    try {
      await api('/api/callsigns', {
        method: 'POST',
        body: { callsign: $('#csr-callsign').value, comment: $('#csr-comment').value }
      });
      closeModal();
      toast('Заявка отправлена командованию', 'success');
      SECTIONS.profile($('#content'));
    } catch (e) { modalError(e.message); }
  });
}

