+
+/* =========================================================
+   Фон: город, улица, машины, пешеходы
+   ========================================================= */
+.bg-city {
+  position: absolute; left: 0; right: 0; bottom: 34px; width: 100%; height: 34vh; min-height: 150px;
+  opacity: .8; filter: blur(.4px);
+}
+.city-windows rect { animation: winFlicker 7s infinite; }
+.city-windows rect:nth-child(2n) { animation-delay: 1.7s; }
+.city-windows rect:nth-child(3n) { animation-delay: 3.1s; }
+.city-windows rect:nth-child(5n) { animation-delay: 4.6s; }
+@keyframes winFlicker {
+  0%, 88%, 100% { opacity: .85; }
+  90% { opacity: .15; }
+  92% { opacity: .7; }
+  95% { opacity: .25; }
+}
+.bg-street {
+  position: absolute; left: 0; right: 0; bottom: 0; height: 46px;
+  background: linear-gradient(180deg, #0b1120 0%, #070b16 40%, #05070d 100%);
+  border-top: 1px solid rgba(122, 154, 224, .12);
+}
+.bg-street::after {
+  content: ''; position: absolute; left: 0; right: 0; top: 55%; height: 2px;
+  background: repeating-linear-gradient(90deg, rgba(255, 217, 122, .28) 0 26px, transparent 26px 60px);
+}
+.car { position: absolute; bottom: 6px; width: 54px; height: 16px; }
+.car .car-body {
+  position: absolute; inset: 0;
+  background: linear-gradient(180deg, #101a30 0%, #060a14 100%);
+  border-radius: 5px 8px 3px 3px;
+  box-shadow: 0 2px 6px rgba(0, 0, 0, .7);
+}
+.car .car-body::before {
