+  background: #0c1424; border-radius: 4px 6px 0 0;
+}
+.car .car-light {
+  position: absolute; top: 5px; width: 46px; height: 5px; border-radius: 50%;
+  background: linear-gradient(90deg, rgba(255, 240, 180, .5), transparent);
+  filter: blur(2px);
+}
+.car-r { animation: driveR linear infinite; }
+.car-r .car-light { right: -40px; }
+.car-l { animation: driveL linear infinite; transform: scaleX(-1); }
+.car-l .car-light { right: -40px; }
+.car-1 { animation-duration: 17s; animation-delay: -3s; bottom: 22px; opacity: .8; transform: scale(.8); }
+.car-2 { animation-duration: 12s; animation-delay: -9s; }
+.car-3 { animation-duration: 15s; animation-delay: -5s; bottom: 4px; }
+@keyframes driveR { from { left: -90px; } to { left: 105%; } }
+@keyframes driveL { from { left: 105%; } to { left: -90px; } }
+.walker { position: absolute; bottom: 30px; width: 26px; height: 46px; opacity: .9; }
+.walker svg { width: 100%; height: 100%; display: block; }
+.walker-1 { animation: walkR 46s linear infinite; animation-delay: -8s; }
+.walker-2 { animation: walkL 58s linear infinite; animation-delay: -30s; width: 30px; height: 52px; }
+.walker-3 { animation: walkR 64s linear infinite; animation-delay: -40s; transform: scale(.85); }
+.walker-4 { animation: walkL 50s linear infinite; animation-delay: -12s; width: 30px; height: 52px; }
+@keyframes walkR {
+  from { left: -40px; }
+  to { left: 104%; }
+}
+@keyframes walkL {
+  from { left: 104%; }
+  to { left: -40px; }
+}
+.walker { animation-name: walkR; }
+.walker-1 svg, .walker-3 svg { animation: stepBob .9s ease-in-out infinite; }
+.walker-2 svg, .walker-4 svg { animation: stepBob 1.05s ease-in-out infinite; }
+.walker-2, .walker-4 { direction: rtl; }
+.walker-2 svg, .walker-4 svg { transform-origin: 50% 100%; }
+@keyframes stepBob {
+  0%, 100% { translate: 0 0; rotate: .6deg; }
+  50% { translate: 0 -2px; rotate: -.6deg; }
+}
+.walker-2, .walker-4 { animation-direction: reverse; }
+
+/* =========================================================
