/* Убирает светлый «шахматный» фон у public/img/gerb.png, делая его прозрачным.
   Запуск: node tools/strip-gerb-bg.js [путь_к_png] */
'use strict';
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const file = process.argv[2] || path.join(__dirname, '..', 'public', 'img', 'gerb.png');
const buf = fs.readFileSync(file);

/* ---- разбор PNG ---- */
let off = 8;
const idat = [];
let w = 0, h = 0, bd = 0, ct = 0;
while (off < buf.length) {
  const len = buf.readUInt32BE(off);
  const type = buf.slice(off + 4, off + 8).toString('ascii');
  if (type === 'IHDR') { w = buf.readUInt32BE(off + 8); h = buf.readUInt32BE(off + 12); bd = buf[off + 16]; ct = buf[off + 17]; }
  if (type === 'IDAT') idat.push(buf.slice(off + 8, off + 8 + len));
  off += 12 + len;
  if (type === 'IEND') break;
}
if (bd !== 8 || ct !== 6) { console.error('Ожидается PNG RGBA 8 бит (colorType 6), получено:', bd, ct); process.exit(1); }

const raw = zlib.inflateSync(Buffer.concat(idat));
const bpp = 4, stride = w * bpp;
const px = Buffer.alloc(h * stride);

/* ---- unfilter ---- */
let pos = 0;
for (let y = 0; y < h; y++) {
  const f = raw[pos++];
  const row = y * stride;
  const prev = y > 0 ? (y - 1) * stride : -1;
  for (let x = 0; x < stride; x++) {
    const a = x >= bpp ? px[row + x - bpp] : 0;
    const b = prev >= 0 ? px[prev + x] : 0;
    const c = (x >= bpp && prev >= 0) ? px[prev + x - bpp] : 0;
    let v = raw[pos + x];
    switch (f) {
      case 1: v += a; break;
      case 2: v += b; break;
      case 3: v += (a + b) >> 1; break;
      case 4: {
        const p = a + b - c;
        const da = Math.abs(p - a), db = Math.abs(p - b), dc = Math.abs(p - c);
        v += (da <= db && da <= dc) ? a : (db <= dc ? b : c);
        break;
      }
    }
    px[row + x] = v & 255;
  }
  pos += stride;
}

/* ---- flood fill от краёв по светлым пикселям фона ---- */
const isBgLike = (o, minV) => {
  const r = px[o], g = px[o + 1], b = px[o + 2];
  const mn = Math.min(r, g, b), mx = Math.max(r, g, b);
  return mn >= minV && (mx - mn) <= 25;
};
const removed = new Uint8Array(w * h);
const stack = [];
for (let x = 0; x < w; x++) { stack.push(x, x + (h - 1) * w); }
for (let y = 0; y < h; y++) { stack.push(y * w, y * w + w - 1); }
while (stack.length) {
  const i = stack.pop();
  if (removed[i]) continue;
  const o = i * bpp;
  if (!isBgLike(o, 185)) continue;
  removed[i] = 1;
  px[o + 3] = 0;
  const x = i % w, y = (i / w) | 0;
  if (x > 0) stack.push(i - 1);
  if (x < w - 1) stack.push(i + 1);
  if (y > 0) stack.push(i - w);
  if (y < h - 1) stack.push(i + w);
}
/* мягкая кромка: одинокие светлые пиксели рядом с удалённым фоном */
for (let y = 0; y < h; y++) {
  for (let x = 0; x < w; x++) {
    const i = y * w + x;
    if (removed[i]) continue;
    const o = i * bpp;
    if (!isBgLike(o, 200)) continue;
    const nb = (x > 0 && removed[i - 1]) || (x < w - 1 && removed[i + 1]) || (y > 0 && removed[i - w]) || (y < h - 1 && removed[i + w]);
    if (nb) { removed[i] = 1; px[o + 3] = 0; }
  }
}

/* ---- сборка PNG ---- */
const out = Buffer.alloc(h * (stride + 1));
for (let y = 0; y < h; y++) {
  out[y * (stride + 1)] = 0;
  px.copy(out, y * (stride + 1) + 1, y * stride, (y + 1) * stride);
}
const CRC_TABLE = (() => {
  const t = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c;
  }
  return t;
})();
const crc32 = (b) => {
  let c = -1;
  for (let i = 0; i < b.length; i++) c = CRC_TABLE[(c ^ b[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ -1) >>> 0;
};
const chunk = (type, data) => {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
};
const ihdr = Buffer.alloc(13);
ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
const png = Buffer.concat([
  Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]),
  chunk('IHDR', ihdr),
  chunk('IDAT', zlib.deflateSync(out, { level: 9 })),
  chunk('IEND', Buffer.alloc(0))
]);
fs.writeFileSync(file, png);
let n = 0; for (let i = 0; i < removed.length; i++) if (removed[i]) n++;
console.log(`Готово: ${file} — прозрачных пикселей ${n} из ${w * h} (${Math.round(100 * n / (w * h))}%)`);

/* Загружает базу законодательства RMRP с forum.rmrp.ru/forums/laws/ в data/laws.json
   для нейро-помощника портала. Запуск: node tools/fetch-laws.js */
'use strict';
const fs = require('fs');
const path = require('path');

const BASE = 'https://forum.rmrp.ru';
const FORUM = '/forums/laws/';
const PAGES = 3;
const OUT = path.join(__dirname, '..', 'data', 'laws.json');
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) GROM-portal-laws-bot/1.0';

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function get(url) {
  const res = await fetch(BASE + url, { headers: { 'User-Agent': UA, 'Accept': 'text/html' } });
  if (!res.ok) throw new Error(`HTTP ${res.status} для ${url}`);
  return res.text();
}

function decodeEntities(s) {
  return String(s)
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&#(\d+);/g, (m, d) => String.fromCharCode(+d));
}

function stripHtml(html) {
  return decodeEntities(
    html
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n')
      .replace(/<li[^>]*>/gi, '\n— ')
      .replace(/<[^>]+>/g, '')
  )
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[^\S\n]{2,}/g, ' ')
    .trim();
}

function shortName(title) {
  const t = title.toLowerCase();
  if (t.includes('уголовно-процессуальный')) return 'УПК РФ';
  if (t.includes('уголовный')) return 'УК РФ';
  if (t.includes('административных')) return 'КоАП РФ';
  if (t.includes('процессуальный')) return 'ПК РФ';
  if (t.includes('трудовой')) return 'ТК РФ';
  if (t.includes('бюджетный')) return 'БК РФ';
  if (t.includes('избирательный')) return 'ИК РФ';
  if (t.includes('конституция')) return 'Конституция РФ';
  if (t.includes('гражданский')) return 'ГК РФ';
  if (t.includes('налоговый')) return 'НК РФ';
  if (t.includes('семейный')) return 'СК РФ';
  if (t.includes('земельный')) return 'ЗК РФ';
  return title;
}

function splitArticles(text) {
  const re = /(?:^|\n)[ \t]*(?:Статья|Ст\.|СТАТЬЯ)\s*(\d+(?:[.\-]\d+)*)[.)]?\s*([^\n]*)/g;
  const hits = [];
  let m;
  while ((m = re.exec(text))) hits.push({ idx: m.index, num: m[1], title: m[2].trim() });
  if (hits.length < 3) return [{ num: '', title: '', text: text.slice(0, 8000) }];
  const arts = [];
  for (let i = 0; i < hits.length; i++) {
    const start = hits[i].idx;
    const end = i + 1 < hits.length ? hits[i + 1].idx : text.length;
    arts.push({
      num: hits[i].num,
      title: hits[i].title.slice(0, 200),
      text: text.slice(start, end).trim().slice(0, 4000)
    });
  }
  return arts;
}

(async () => {
  console.log('[laws] Сбор списка тем раздела «Общее законодательство»...');
  const threads = new Map();
  for (let p = 1; p <= PAGES; p++) {
    const url = p === 1 ? FORUM : `${FORUM}page-${p}`;
    let html;
    try { html = await get(url); } catch (e) { console.log('[laws] страница', p, ':', e.message); break; }
    const re = /<a href="(\/threads\/[^"]+?\/)"[^>]*data-tp-primary="on"[^>]*>([^<]+)<\/a>/g;
    let m;
    while ((m = re.exec(html))) {
      if (!threads.has(m[1])) threads.set(m[1], decodeEntities(m[2]).trim());
    }
    await sleep(400);
  }
  console.log(`[laws] Найдено тем: ${threads.size}`);
  if (!threads.size) { console.error('[laws] Не удалось получить список тем'); process.exit(1); }

  const codes = [];
  const laws = [];
  let i = 0;
  for (const [url, title] of threads) {
    i++;
    laws.push({ title, url: BASE + url });
    try {
      const html = await get(url);
      const start = html.indexOf('<div class="bbWrapper">');
      if (start === -1) { console.log(`[laws] ${i}/${threads.size} ${title}: нет тела поста`); continue; }
      let slice = html.slice(start + '<div class="bbWrapper">'.length);
      const cut = slice.search(/<article|<footer|<ul class="message-notes/);
      if (cut > 0) slice = slice.slice(0, cut);
      const text = stripHtml(slice);
      if (text.length < 40) { console.log(`[laws] ${i}/${threads.size} ${title}: пустое тело`); continue; }
      codes.push({ title, short: shortName(title), url: BASE + url, articles: splitArticles(text) });
      console.log(`[laws] ${i}/${threads.size} ${title}: ${text.length} симв., статей: ${codes[codes.length - 1].articles.length}`);
    } catch (e) {
      console.log(`[laws] ${i}/${threads.size} ${title}: ошибка — ${e.message}`);
    }
    await sleep(500);
  }

  const out = { source: BASE + FORUM, updated: new Date().toISOString(), codes, laws };
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, JSON.stringify(out), 'utf8');
  const total = codes.reduce((s, c) => s + c.articles.length, 0);
  console.log(`[laws] Готово: ${codes.length} актов, ${total} статей → ${OUT}`);
})().catch(e => { console.error('[laws] Фатальная ошибка:', e); process.exit(1); });

