const BASE = 'http://127.0.0.1:3000';
const j = (r) => r.json();
async function login(username, password) {
  const r = await fetch(BASE + '/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username, password }) });
  const d = await j(r);
  return { token: d.token, user: d.user, status: r.status };
}
async function api(token, path, opts = {}) {
  const r = await fetch(BASE + path, { method: opts.method || 'GET', headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: 'Bearer ' + token } : {}) }, body: opts.body ? JSON.stringify(opts.body) : undefined });
  let d = null; try { d = await r.json(); } catch (e) {}
  return { status: r.status, d };
}
(async () => {
  const cmd = await login('monsieurpenis', 'grom2026');
  console.log('LOGIN commander:', cmd.status, cmd.user && cmd.user.fio, cmd.user && cmd.user.role);
  const t = cmd.token;

  const info = await api(t, '/api/ai/info');
  console.log('AI INFO:', info.status, 'codes=', info.d && info.d.codes && info.d.codes.length, 'updated=', info.d && info.d.updated);

  const ai = await api(t, '/api/ai', { method: 'POST', body: { question: 'какое наказание за убийство?' } });
  console.log('AI ANSWER:', ai.status);
  if (ai.d && ai.d.answer) {
    console.log('  text head:', ai.d.answer.text.slice(0, 160).replace(/\n/g, ' '));
    console.log('  sources:', ai.d.answer.sources.length);
