  console.log('AI ANSWER2:', ai2.status, ai2.d.answer ? ai2.d.answer.text.slice(0, 120).replace(/\n/g, ' ') : ai2.d);

  const qa = await api(t, '/api/qa', { method: 'POST', body: { title: 'Тестовый вопрос отладки', text: 'Проверяю работу раздела вопросов и ответов портала.' } });
  console.log('QA CREATE:', qa.status, qa.d.question && qa.d.question.id);
  if (qa.d.question) {
    const ans = await api(t, `/api/qa/${qa.d.question.id}/answers`, { method: 'POST', body: { text: 'Тестовый ответ командования.' } });
    console.log('QA ANSWER:', ans.status, 'answers=', ans.d.question && ans.d.question.answers.length);
    const sol = await api(t, '/api/qa/' + qa.d.question.id, { method: 'PATCH', body: { solved: true } });
    console.log('QA SOLVE:', sol.status, 'solved=', sol.d.question && sol.d.question.solved);
    const del = await api(t, '/api/qa/' + qa.d.question.id, { method: 'DELETE' });
    console.log('QA DELETE:', del.status);
  }

  const msg = await api(t, '/api/chat', { method: 'POST', body: { text: 'Тестовое сообщение для проверки редактирования' } });
  console.log('CHAT SEND:', msg.status, msg.d.message && msg.d.message.id);
  if (msg.d.message) {
    const id = msg.d.message.id;
    const ed = await api(t, '/api/chat/' + id, { method: 'PATCH', body: { text: 'Отредактированный текст' } });
    console.log('CHAT EDIT:', ed.status, 'editedAt?', !!(ed.d.message && ed.d.message.editedAt), 'text=', ed.d.message && ed.d.message.text);
    const de = await api(t, '/api/chat/' + id, { method: 'DELETE' });
    console.log('CHAT DELETE:', de.status);
  }

  const staff = await login('werewolf_1337', 'grom2026');
  console.log('LOGIN deputy:', staff.status, staff.user && staff.user.role);
  const newUser = await api(staff.token, '/api/users', { method: 'POST', body: { username: 'test_op_' + Date.now().toString(36), password: 'grom2026', fio: 'Тестов Тест Тестович', rank: 'Стажёр', post: 'Стажёр «ГРОМ»', role: 'staff' } });
  console.log('DEPUTY CREATE USER:', newUser.status, newUser.d.error || (newUser.d.user && newUser.d.user.username));
})().catch(e => { console.error('FATAL', e); process.exit(1); });

