  console.log(`«${q}»\n   → ${first}\n   источников: ${d.answer.sources.map(s => s.title.slice(0, 40)).join(' | ')}`);
}
(async () => {
  const t = await login('monsieurpenis', 'grom2026');
  for (const q of ['наказание за убийство', 'статья за кражу', 'что грозит за хранение оружия', 'как проводится обыск', 'ответственность за угон автомобиля', 'оскорбление сотрудника']) await ask(t, q);
})();

