  'законно': 'закон', 'законы': 'закон', 'статьи': 'статья', 'статей': 'статья', 'статью': 'статья',
};
function expandTokens(tokens) {
  const out = new Set(tokens);
  for (const t of tokens) {
    if (SYN[t]) tokenize(SYN[t]).forEach(w => out.add(w));
    const st = stem(t);
    for (const k in SYN) { if (stem(k) === st) tokenize(SYN[k]).forEach(w => out.add(w)); }
  }
  return [...out];
}
