function aiReply(question, history) {
  const q = String(question).trim();
  const ql = q.toLowerCase();
  // math
  const math = tryMath(ql);
  if (math) return { text: math, sources: [], score: 0 };
  // time
  if (AI_INTENTS time) ...
  for (const it of AI_INTENTS) { if (it.re.test(ql)) return { text: aiTalk(it.kind), sources: [] }; }
  // context
  const merged = withContext(q, history);
  // laws
  const law = lawsAnswer(merged);
  if (law.score >= 9) return law;
  // kb
  const kb = kbSearch(merged);
  if (kb && kb.score >= 3) return { text: kb.text, sources: kb.sources || [] };
  if (law.score >= 6) return law;
  if (kb && kb.score >= 2) return { text: kb.text, sources: [] };
  // fallback
  return { text: fallbackText(q), sources: [] };
}
```

kbSearch:
```
function kbSearch(q) {
  const toks = tokenize(q);
  const raw = q.toLowerCase().split(/[^a-zа-я0-9]+/).filter(Boolean);
  let best = null;
  for (const e of KB) {
    let score = 0;
    for (const k of e.keys) {
      const ks = stem(k);
      if (raw.includes(k) || toks.includes(k)) score += 3;
      else if (toks.some(t => stem(t) === ks) || raw.some(t => stem(t) === ks)) score += 2;
    }
    // bonus: title words in query
    if (score && (!best || score > best.score)) best = { score, text: `📘 ${e.title}\n${e.text}`, entry: e };
  }
  return best;
}
```
Threshold: single key stem match = 2 → need >=3? Set: strong >=3 (exact key or key+stem), weak >=2.

