```
function withContext(q, history) {
  const toks = tokenize(q);
  if (toks.length >= 3 || !Array.isArray(history) || !history.length) return q;
  const prev = [...history].reverse().find(m => m && m.role === 'user' && m.text !== q);
  if (!prev) return q;
  const pt = tokenize(prev.text);
  if (pt.length < 3) return q;
  return prev.text + ' ' + q;
}
```

