```
function tryMath(ql) {
  let cand = ql.replace(/(сколько\s+будет|посчитай|вычисли|калькулятор|сколько|=|\?)/g, ' ').replace(/,/g, '.').trim();
  cand = cand.replace(/\s+/g, ' ');
  if (!/^[0-9+\-*/(). ]+$/.test(cand) || !/[0-9]/.test(cand) || !/[+\-*/]/.test(cand)) return null;
  if ((cand.match(/[0-9]/g) || []).length < 1) return null;
  try {
    const v = Function('"use strict";return (' + cand + ')')();
    if (typeof v === 'number' && isFinite(v)) return `🧮 ${cand.replace(/\s+/g, ' ').trim()} = ${Math.round(v * 1e6) / 1e6}`;
  } catch (e) {}
  return null;
}
```
Note: the charset restriction makes Function safe.

