const fs = require('fs');
function cut(file, startMarker, endMarker) {
  let s = fs.readFileSync(file, 'utf8');
  const a = s.indexOf(startMarker);
  const b = s.indexOf(endMarker);
  if (a < 0) { console.log(file, ': start marker NOT FOUND'); return; }
  if (b < 0 || b < a) { console.log(file, ': end marker NOT FOUND'); return; }
  s = s.slice(0, a) + s.slice(b);
  fs.writeFileSync(file, s);
  console.log(file, ': removed', b - a, 'chars');
}
